'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const audio=$('#audio');let db,tracks=[],current=null,view='all',shuffle=false,repeat='off',url=null,toastTimer,installPrompt=null;
const time=s=>Number.isFinite(s)?`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`:'0:00';
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function showDialog(html){$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
$('#dialog-close').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('sojang-music',1);r.onupgradeneeded=()=>r.result.createObjectStore('tracks',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function transaction(mode,action){return new Promise((resolve,reject)=>{const tx=db.transaction('tracks',mode);let request;try{request=action(tx.objectStore('tracks'))}catch(e){reject(e);return}tx.oncomplete=()=>resolve(request?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('저장이 취소됐습니다'))})}
async function persist(track){await transaction('readwrite',s=>s.put(track))}
function visible(){let list=tracks.filter(t=>(view!=='favorites'||t.favorite)&&(view!=='recent'||t.lastPlayed));const q=$('#search').value.trim().toLocaleLowerCase();if(q)list=list.filter(t=>(t.title+' '+t.artist).toLocaleLowerCase().includes(q));return list.sort((a,b)=>view==='recent'?(b.lastPlayed||0)-(a.lastPlayed||0):$('#sort').value==='name'?a.title.localeCompare(b.title,'ko'):b.added-a.added)}
function glyph(name){return `<svg class="glyph" viewBox="0 0 24 24" aria-hidden="true"><g class="ink-frame" filter="url(#ink-0)"><use href="#glyph-${name}"/></g><g class="ink-frame" filter="url(#ink-1)"><use href="#glyph-${name}"/></g><g class="ink-frame" filter="url(#ink-2)"><use href="#glyph-${name}"/></g><g class="ink-frame" filter="url(#ink-3)"><use href="#glyph-${name}"/></g></svg>`}
function setGlyph(node,name){if(node.dataset.currentGlyph===name)return;node.innerHTML=glyph(name);node.dataset.currentGlyph=name}
$$('[data-glyph]').forEach(node=>setGlyph(node,node.dataset.glyph));
function render(){const list=visible();$('#count').textContent=String(list.length).padStart(2,'0');$('#side-count').textContent=tracks.length;$('#view-title').firstChild.textContent=({all:'레코드장 ',favorites:'좋아하는 레코드 ',recent:'최근 재생 '})[view];$$('[data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===view);el.setAttribute('aria-pressed',el.dataset.view===view)});$('#collection-info').textContent=tracks.length?`${list.length}장 · ${formatSize(list.reduce((a,t)=>a+(t.blob?.size||0),0))} · 기기에 보관 중`:'나만의 작은 레코드장';$('#play-all').disabled=!list.length;$('#empty').hidden=list.length>0;$('#tracks').innerHTML=list.map((t,i)=>`<article class="track" data-id="${t.id}"><button class="track-art art-${t.color||'a'} ${t.cover?'has-cover':''}" data-action="play" aria-label="${escapeHTML(t.title)}, ${escapeHTML(t.artist)} 재생"><span class="sleeve"><span class="sleeve-top">LPP / PRIVATE PRESS</span><strong class="sleeve-title">${escapeHTML(t.title)}</strong><span class="sleeve-bottom"><span>SIDE ${String(i+1).padStart(2,'0')}</span><span>33⅓ RPM</span></span></span>${current?.id===t.id?`<span class="playing-badge">${glyph(audio.paused?'pause':'disc')}</span>`:''}</button><div class="track-bottom"><button class="track-info" data-action="play"><span class="track-title">${escapeHTML(t.title)}</span><span class="track-artist">${escapeHTML(t.artist)}${t.demo?' · 예시':''}</span><span class="track-duration">${time(t.duration)}</span></button><button class="icon ${t.favorite?'liked':''}" data-action="like" aria-label="${escapeHTML(t.title)} 좋아요 ${t.favorite?'취소':'추가'}" aria-pressed="${!!t.favorite}">${glyph('heart')}</button><button class="icon more" data-action="more" aria-label="${escapeHTML(t.title)} 관리">${glyph('more')}</button></div></article>`).join('');list.forEach(t=>{if(t.cover)$(`[data-id="${t.id}"] .track-art`).style.backgroundImage=`url("${t.cover}")`});
if(!list.length){const filtered=tracks.length>0;$('#empty h3').textContent=filtered?(view==='favorites'?'좋아하는 레코드를 모아보세요':view==='recent'?'아직 이곳은 조용하네요':'찾는 레코드가 없어요'):'첫 번째 프레스를 기다려요';$('#empty p').textContent=filtered?(view==='favorites'?'레코드 옆 하트에 나만의 취향을 담아두세요.':view==='recent'?'음악을 들으면 이곳에 재생 기록이 남아요.':'검색어를 바꾸거나 새로운 음악을 담아보세요.'):'파일 앱에서 음악을 가져와 나만의 레코드장을 채워보세요.';$('#load-demo').hidden=tracks.some(t=>t.demo);}
updatePlayer()}
function formatSize(n){return n>1024*1024?`${(n/1024/1024).toFixed(1)} MB`:`${Math.round(n/1024)} KB`}
function updatePlayer(){const playing=!!current&&!audio.paused;setGlyph($('#play'),playing?'pause':'play');setGlyph($('#mini-play'),playing?'pause':'play');$('#play').setAttribute('aria-label',playing?'일시정지':'재생');$('#mini-play').setAttribute('aria-label',playing?'일시정지':'재생');$('#now-title').textContent=current?.title||'레코드를 골라주세요';$('#now-artist').textContent=current?(current.artist+(current.demo?' · 예시 레코드':'')):'LPP · Private Press';$('#mini-title').textContent=current?.title||'첫 번째 레코드를 담아보세요';$('#mini-artist').textContent=current?.artist||'LPP · PRIVATE PRESS';$('#now-like').disabled=!current;$('#now-like').classList.toggle('liked',!!current?.favorite);$('#now-like').setAttribute('aria-pressed',!!current?.favorite);$('#now-like').setAttribute('aria-label',current?.favorite?'현재 곡 좋아요 취소':'현재 곡 좋아요 추가');$('#seek').disabled=!current||!Number.isFinite(audio.duration);const cover=$('#cover'),mini=$('#open-player');cover.className=`cover art-${current?.color||'a'}`;$('.center-label').style.backgroundImage=current?.cover?`url("${current.cover}")`:'';$('.cover-label').hidden=!!current?.cover;mini.style.backgroundImage=current?.cover?`url("${current.cover}")`:'';mini.querySelector('.glyph').style.opacity=current?.cover?'0':'1';document.body.classList.toggle('playing',playing);$('#spin-caption').textContent=playing?'THE RECORD IS SPINNING':'TAKE YOUR TIME';}
async function selectTrack(id,play=true){const track=tracks.find(t=>t.id===id);if(!track)return;const changed=current?.id!==id;if(changed){audio.pause();if(url)URL.revokeObjectURL(url);current=track;url=URL.createObjectURL(track.blob);audio.src=url;audio.load();$('#elapsed').textContent='0:00';$('#seek').value=0;$('#duration').textContent=time(track.duration);if('mediaSession'in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:track.title,artist:track.artist,album:'LPP · Private Press',artwork:[{src:track.cover||new URL('icon-512.png',location.href).href,sizes:'512x512',type:track.cover?'image/jpeg':'image/png'}]})}}render();if(play){try{await audio.play();track.lastPlayed=Date.now();await persist(track);render()}catch(e){if(e.name!=='AbortError')toast('재생할 수 없습니다. 파일 형식이나 기기 볼륨을 확인해 주세요.')}}}
function togglePlay(){if(!current){const first=visible()[0]||tracks[0];if(first)selectTrack(first.id);else toast('먼저 음악을 가져와 주세요');return}if(audio.paused)selectTrack(current.id);else audio.pause()}
function advance(direction,automatic=false){let list=visible();if(!list.some(t=>t.id===current?.id))list=[...tracks].sort((a,b)=>b.added-a.added);if(!list.length)return;if(shuffle&&list.length>1){const options=list.filter(t=>t.id!==current?.id);selectTrack(options[Math.floor(Math.random()*options.length)].id);return}const i=list.findIndex(t=>t.id===current?.id),next=i+direction;if(automatic&&next>=list.length&&repeat==='off'){audio.currentTime=0;updatePlayer();return}selectTrack(list[(next+list.length)%list.length].id)}
async function toggleLike(t){if(!t)return;const value=!t.favorite;try{await persist({...t,favorite:value});t.favorite=value;render()}catch{toast('좋아요를 저장하지 못했습니다')}}
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;$('#search').value='';render()});$('#search').oninput=render;$('#sort').onchange=render;
$('#tracks').onclick=e=>{const b=e.target.closest('[data-action]'),row=e.target.closest('[data-id]');if(!b||!row)return;const t=tracks.find(t=>t.id===row.dataset.id);if(b.dataset.action==='play')selectTrack(t.id);if(b.dataset.action==='like')toggleLike(t);if(b.dataset.action==='more')manageTrack(t)};
$('#play').onclick=$('#mini-play').onclick=togglePlay;$('#next').onclick=$('#mini-next').onclick=()=>advance(1);$('#previous').onclick=()=>{if(audio.currentTime>3)audio.currentTime=0;else advance(-1)};$('#now-like').onclick=()=>toggleLike(current);$('#play-all').onclick=()=>{const list=visible();if(list.length)selectTrack(list[0].id)};
$('#shuffle').onclick=()=>{shuffle=!shuffle;$('#shuffle').classList.toggle('enabled',shuffle);$('#shuffle').setAttribute('aria-pressed',shuffle);$('#shuffle').setAttribute('aria-label',shuffle?'셔플 켜짐':'셔플 꺼짐');toast(shuffle?'순서를 섞어서 재생합니다':'순서대로 재생합니다')};
$('#repeat').onclick=()=>{repeat=repeat==='off'?'all':repeat==='all'?'one':'off';$('#repeat').classList.toggle('enabled',repeat!=='off');$('#repeat').innerHTML=glyph('repeat')+(repeat==='one'?'<span class="repeat-one">1</span>':'');$('#repeat').setAttribute('aria-pressed',repeat!=='off');$('#repeat').setAttribute('aria-label',({off:'반복 꺼짐',all:'전체 반복',one:'한 곡 반복'})[repeat]);toast(({off:'반복 재생을 껐습니다',all:'보관함 전체를 반복합니다',one:'현재 곡을 반복합니다'})[repeat])};
$('#seek').oninput=e=>{if(Number.isFinite(audio.duration))audio.currentTime=Number(e.target.value)*audio.duration/100};audio.volume=.8;$('#volume').oninput=e=>{audio.volume=Number(e.target.value);$('#volume-value').textContent=`${Math.round(audio.volume*100)}%`};audio.ontimeupdate=()=>{$('#elapsed').textContent=time(audio.currentTime);$('#seek').value=audio.duration?audio.currentTime/audio.duration*100:0;$('#mini-progress-bar').style.width=`${audio.duration?audio.currentTime/audio.duration*100:0}%`};audio.onloadedmetadata=()=>{$('#duration').textContent=time(audio.duration);$('#seek').disabled=!Number.isFinite(audio.duration);if(current&&Number.isFinite(audio.duration)&&Math.abs((current.duration||0)-audio.duration)>.5){current.duration=audio.duration;persist(current).then(render).catch(()=>{})}};audio.onplay=audio.onpause=()=>{updatePlayer();render()};audio.onended=()=>{if(repeat==='one'){audio.currentTime=0;audio.play().catch(()=>toast('재생 버튼을 눌러 주세요'))}else advance(1,true)};audio.onerror=()=>{if(current)toast('이 기기에서 재생할 수 없는 파일입니다. MP3 또는 M4A로 다시 시도해 주세요.')};
function metadata(file){return new Promise(resolve=>{const a=new Audio(),u=URL.createObjectURL(file);const finish=()=>{clearTimeout(timer);const duration=Number.isFinite(a.duration)?a.duration:0;a.removeAttribute('src');a.load();URL.revokeObjectURL(u);resolve(duration)};const timer=setTimeout(finish,5000);a.onloadedmetadata=a.onerror=finish;a.src=u})}
async function importFiles(files){if(!db){toast('보관함을 아직 열지 못했습니다. 새로고침해 주세요.');return}let added=0,duplicates=0,failed=0;const candidates=[...files];toast('음악을 기기에 저장하는 중…');for(const file of candidates){if(!file.type.startsWith('audio/')&&!/\.(mp3|m4a|wav|ogg|flac|aac|aiff|opus)$/i.test(file.name)){failed++;continue}if(tracks.some(t=>t.filename===file.name&&t.blob.size===file.size)){duplicates++;continue}try{const duration=await metadata(file),name=file.name.replace(/\.[^.]+$/,'');const parts=name.split(' - ');const t={id:crypto.randomUUID(),title:parts.length>1?parts.slice(1).join(' - '):name,artist:parts.length>1?parts[0]:'나의 음악',filename:file.name,blob:file,duration,added:Date.now(),favorite:false,color:['a','b','c'][tracks.length%3]};await persist(t);tracks.push(t);added++;render()}catch{failed++}}if(added&&navigator.storage?.persist)navigator.storage.persist().catch(()=>{});toast([added?`${added}곡을 레코드장에 담았습니다`:'',duplicates?`중복 ${duplicates}곡 건너뜀`:'',failed?`${failed}개 저장 실패 · 파일 형식과 여유 공간을 확인해 주세요`:'' ].filter(Boolean).join(' · ')||'추가할 파일이 없습니다');$('#files').value=''}
['add-top','add-small','add-empty'].forEach(id=>$('#'+id).onclick=()=>$('#files').click());$('#files').onchange=e=>importFiles(e.target.files);document.addEventListener('dragover',e=>{e.preventDefault();document.body.classList.add('dragging')});document.addEventListener('dragleave',e=>{if(!e.relatedTarget)document.body.classList.remove('dragging')});document.addEventListener('drop',e=>{e.preventDefault();document.body.classList.remove('dragging');importFiles(e.dataTransfer.files)});
$('#load-demo').onclick=async()=>{const button=$('#load-demo');button.disabled=true;try{const response=await fetch('sample.wav');if(!response.ok)throw Error();const blob=await response.blob();const track={id:crypto.randomUUID(),title:'First Press',artist:'LPP Studio',filename:'sojang-sample.wav',blob,duration:18,added:Date.now(),favorite:false,color:'a',demo:true};await persist(track);tracks.push(track);render();selectTrack(track.id,false);toast('직접 합성한 18초 예시 음악입니다. 재생을 눌러보세요.')}catch{toast('예시 음악을 가져오지 못했습니다. 인터넷 연결을 확인해 주세요.')}finally{button.disabled=false}};
function manageTrack(t){showDialog(`<div class="eyebrow muted">TRACK DETAILS</div><h2>음악 관리</h2><form id="edit-form"><label class="form-label">곡 제목<input id="edit-title" value="${escapeHTML(t.title)}" required maxlength="120"></label><label class="form-label">아티스트<input id="edit-artist" value="${escapeHTML(t.artist)}" required maxlength="100"></label><label class="form-label">앨범 이미지<input id="edit-cover" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="dialog-row"><span>파일 크기</span>${formatSize(t.blob.size)}</div><div class="dialog-actions"><button type="button" id="delete-track" class="text-button">곡 삭제</button><button class="primary" type="submit">저장</button></div></form>`);$('#edit-form').onsubmit=async e=>{e.preventDefault();const copy={...t,title:$('#edit-title').value.trim(),artist:$('#edit-artist').value.trim()};if(!copy.title||!copy.artist)return;try{const file=$('#edit-cover').files[0];if(file)copy.cover=await resizeCover(file);await persist(copy);Object.assign(t,copy);render();if(current?.id===t.id&&'mediaSession'in navigator)navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist});$('#dialog').close();toast('곡 정보를 저장했습니다')}catch{toast('저장하지 못했습니다. 이미지 형식과 여유 공간을 확인해 주세요.')}};$('#delete-track').onclick=()=>{showDialog(`<h2>이 곡을 삭제할까요?</h2><p>‘${escapeHTML(t.title)}’이 LPP 레코드장에서 삭제됩니다. 원본 음악 파일은 그대로 유지됩니다.</p><div class="dialog-actions"><button class="text-button" id="cancel-delete">취소</button><button class="primary danger" id="confirm-delete">삭제</button></div>`);$('#cancel-delete').onclick=()=>$('#dialog').close();$('#confirm-delete').onclick=async()=>{try{await transaction('readwrite',s=>s.delete(t.id));if(current?.id===t.id){audio.pause();audio.removeAttribute('src');audio.load();if(url)URL.revokeObjectURL(url);url=null;current=null;$('#seek').value=0;$('#elapsed').textContent=$('#duration').textContent='0:00';if('mediaSession'in navigator)navigator.mediaSession.metadata=null}tracks=tracks.filter(x=>x.id!==t.id);$('#mini-progress-bar').style.width='0%';render();$('#dialog').close();toast('보관함에서 삭제했습니다')}catch{toast('삭제하지 못했습니다. 다시 시도해 주세요.')}}}}
async function resizeCover(file){const img=new Image(),u=URL.createObjectURL(file);try{img.src=u;await img.decode();const canvas=document.createElement('canvas');canvas.width=canvas.height=512;const ctx=canvas.getContext('2d'),size=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-size)/2,(img.height-size)/2,size,size,0,0,512,512);return canvas.toDataURL('image/jpeg',.85)}finally{URL.revokeObjectURL(u)}}
let offlineReady=false;
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');
let storedMotion;try{storedMotion=localStorage.getItem('lpp-motion')}catch{}
let motion=storedMotion?storedMotion==='on':!reduceMotion.matches;
function applyMotion(){document.documentElement.dataset.motion=motion?'on':'off';const b=$('#motion-toggle');if(b){b.textContent=motion?'움직임 켜짐':'움직임 꺼짐';b.setAttribute('aria-pressed',motion)}}
applyMotion();reduceMotion.addEventListener('change',e=>{motion=!e.matches;applyMotion()});
document.addEventListener('visibilitychange',()=>{document.documentElement.dataset.paused=String(document.hidden)});
async function settings(){const estimate=await navigator.storage?.estimate?.().catch(()=>null);showDialog(`<div class="eyebrow">LPP / PRIVATE PRESS</div><h2>나만의 레코드장</h2><p>말로 다 담지 못한 마음을, 한 장의 음악으로. LPP는 나의 음악을 이 기기에 담아 듣는 개인용 플레이어입니다.</p><div class="dialog-row"><span>지글지글 움직임</span><button id="motion-toggle" class="setting-toggle" aria-pressed="${motion}">${motion?'움직임 켜짐':'움직임 꺼짐'}</button></div><p style="font-size:11px">아이콘의 선과 Noto 기반 Open Cosmos Ink 폰트가 함께 움직입니다. 필요할 때 여기서 멈출 수 있어요.</p><div class="dialog-row"><span>보관 중인 레코드</span>${tracks.length}장</div><div class="dialog-row"><span>음악 파일 용량</span>${formatSize(tracks.reduce((n,t)=>n+t.blob.size,0))}</div>${estimate?`<div class="dialog-row"><span>사이트의 기기 저장 공간 사용량</span>${formatSize(estimate.usage||0)}</div>`:''}<p class="ready-state">${offlineReady?'앱 파일의 오프라인 준비가 완료됐어요.':'오프라인 준비 중 · 인터넷 연결을 유지해 주세요.'}</p><div class="dialog-note">음악 파일과 재킷 이미지는 서버로 전송하지 않고, 이 기기와 브라우저 안에 저장합니다. 다른 기기로는 자동으로 옮겨지지 않습니다.<br><br>브라우저 데이터 삭제·홈 화면 앱 제거·기기 저장 공간 정리로 보관함이 사라질 수 있으니 원본 음악은 따로 보관하세요. 홈 화면에 추가한 뒤 음악을 가져오는 것을 권장합니다.<br><br>화면을 잠그거나 다른 앱으로 전환했을 때 재생 유지 여부는 iOS와 Safari에 따라 달라집니다. 실제 아이폰에서 한 곡을 추가하고 확인해 주세요.</div><button class="primary" id="guide-install">아이폰에서 사용하는 방법</button><p style="font-size:10px">FONT: Open Cosmos Ink KR Full · Noto Serif KR 기반 · <a href="fonts/OFL.txt" target="_blank" rel="noopener">SIL OFL</a></p>`);$('#motion-toggle').onclick=()=>{motion=!motion;applyMotion();try{localStorage.setItem('lpp-motion',motion?'on':'off')}catch{}};$('#guide-install').onclick=install}
$('#settings').onclick=$('#mobile-settings').onclick=settings;
async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null;return}showDialog(`<div class="eyebrow">LPP / TAKE IT WITH YOU</div><h2>내 폰에서 LPP 켜기</h2><p>아이폰 Safari에서 이 주소를 열면 바로 사용할 수 있습니다. Xcode 설치나 앱 서명은 필요 없어요.</p><ol><li>본인의 ChatGPT 계정으로 로그인하세요. 개인용 주소라 본인만 접속할 수 있습니다.</li><li>Safari 공유 버튼 → ‘홈 화면에 추가’를 누르면 앱처럼 꺼내 쓸 수 있어요.</li><li>홈 화면의 LPP를 열고 ‘레코드 가져오기’에서 파일 앱의 MP3·M4A·WAV 등을 선택하세요.</li></ol><div class="dialog-note">브라우저와 홈 화면 앱의 저장소는 환경에 따라 다를 수 있습니다. 홈 화면에 추가한 다음 음악을 가져오세요.<br><br>처음 앱과 폰트를 준비할 때는 인터넷이 필요합니다. 파일 준비가 끝난 후 비행기 모드에서도 직접 실행해 확인해 주세요.</div>`)}
$('#install').onclick=install;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});$('#open-player').onclick=$('#open-player-info').onclick=()=>document.body.classList.add('player-open');$('#close-player').onclick=()=>document.body.classList.remove('player-open');document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('player-open');if(e.code==='Space'&&!/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName)&&!$('#dialog').open){e.preventDefault();togglePlay()}});
if('mediaSession'in navigator){for(const [key,fn] of Object.entries({play:()=>selectTrack(current?.id||visible()[0]?.id),pause:()=>audio.pause(),previoustrack:()=>advance(-1),nexttrack:()=>advance(1),seekto:e=>{if(Number.isFinite(e.seekTime))audio.currentTime=e.seekTime},seekbackward:e=>audio.currentTime=Math.max(0,audio.currentTime-(e.seekOffset||10)),seekforward:e=>audio.currentTime=Math.min(audio.duration||0,audio.currentTime+(e.seekOffset||10))})){try{navigator.mediaSession.setActionHandler(key,fn)}catch{}}}
(async()=>{try{db=await openDB();tracks=await transaction('readonly',s=>s.getAll());render();if(tracks.length)await selectTrack(visible()[0].id,false)}catch{render();toast('기기 저장 공간을 열지 못했습니다. 일반 브라우저에서 다시 열어 주세요.')}if('serviceWorker'in navigator){navigator.serviceWorker.register('sw.js').then(reg=>{function watch(worker){if(!worker)return;worker.addEventListener('statechange',()=>{if(worker.state==='installed'){offlineReady=true;const state=$('.ready-state');if(state)state.textContent='앱 파일의 오프라인 준비가 완료됐어요.'}})}watch(reg.installing);reg.addEventListener('updatefound',()=>watch(reg.installing));if(reg.active&&!reg.installing)offlineReady=true;}).catch(()=>toast('오프라인 준비에 실패했습니다. 인터넷 연결을 유지해 주세요.'))}})();
if(/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1)){const volume=document.querySelector('.volume');volume.innerHTML='<span class="ios-volume-note">음량은 아이폰 옆면 버튼으로 조절하세요</span>';volume.style.justifyContent='center';}
